import br.casasala.painel.*;import org.json.*;
public class VoiceQueueTest{
 static void check(boolean ok,String why)throws Exception{if(!ok)throw new Exception(why);}
 public static void main(String[] args)throws Exception{JellyfinClient c=new JellyfinClient(args[0],"fixture-token","user1","own-device");JSONObject artist=c.voiceSelection("Artista de teste","artist");check(artist.getString("Id").equals("artist1"),"Artist resolution");JSONArray q=c.audioQueue(artist);check(q.length()==450&&q.getJSONObject(0).getString("Id").equals("song0")&&q.getJSONObject(449).getString("Id").equals("song449"),"All artist pages/order");JSONObject genre=c.voiceSelection("samba","genre");check(c.audioQueue(genre).length()==450,"All genre pages");boolean ambiguous=false;try{c.voiceSelection("ambiguous","artist");}catch(Exception expected){ambiguous=true;}check(ambiguous,"Ambiguous artist accepted");check(VoiceIntent.parse("Alexa aumenta o brilho da sala").getJSONObject("action").getInt("delta")==10,"Brightness increment");check(VoiceIntent.parse("Alexa coloca a sala em 50 por cento").getJSONObject("action").getBoolean("preserve_mode"),"Brightness resets RGB");System.out.println("PASS artist/genre resolution, 450 tracks with paging and order, ambiguous rejection, brightness mode preserved.");}
}
